   430  strndup(const char *str, size_t n)
   431  {
   432          size_t len;
   433          char *copy;
   434
   435          for (len = 0; len < n && str[len]; len++)
   436                  continue;
   437          if ((copy = malloc(len + 1)) == NULL)
   438                  return NULL;
   439          (void)memcpy(copy, str, len);
   440          copy[len] = '\0';
   441          return copy;
